from pt import *
items = [
 HDR(),
 T(r"""Then, the sequence of random compact sets $\{\mathcal{Y}^M\}_{M=1}^\infty$ almost surely converges to $\mathcal{Y}$ (in the myopic topology), i.e., almost surely, $d_H(\mathcal{Y}^M,\mathcal{Y})\rightarrow 0$ as $M\rightarrow\infty$.""", [89, 93, 523, 119]),
 H(r"### A.2. Sampling-based reachability analysis", [89, 134, 287, 146]),
 T(r"""As discussed in Section 3, $\epsilon$-RandUP relies on the choice of three parameters:""", [89, 153, 436, 165]),
 T(r"""- a number of samples $M\in\mathbb{N}$,
- a padding constant $\epsilon>0$,
- a probability measure $\mathbb{P}_\mathcal{X}$ on $(\mathbb{R}^{p},\mathcal{B}(\mathbb{R}^{p}))$ such that $\mathbb{P}_\mathcal{X}(\mathcal{X})=1$.""", [107, 175, 400, 225]),
 T(r"""This algorithm consists of sampling $M$ independent identically-distributed inputs $x_i$ according to $\mathbb{P}_\mathcal{X}$, of evaluating each output sample $y_i=f(x_i)$, and of computing the reachable set estimator $\hat{\mathcal{Y}}_\epsilon^M=\mathrm{H}\left(\{y_i\}_{i=1}^M\right)\oplus B(0,\epsilon)$ as in (2).""", [89, 234, 523, 273]),
 T(r"""Formally, let $(\Omega,\mathcal{G},\mathbb{P})$ be a probability space such that the $x_i$'s are $\mathcal{G}$-measurable independent random variables which laws $\mathbb{P}_\mathcal{X}$ satisfy $\mathbb{P}_\mathcal{X}(A)=\mathbb{P}(x_i\in A)$ for any $A\in\mathcal{B}(\mathbb{R}^p)$ $^{3}$. Then, the $y_i$'s are independent random variables which laws $\mathbb{P}_{\mathcal{Y}}$ satisfy $\mathbb{P}_{\mathcal{Y}}(B)=\mathbb{P}(y_i\in B)=\mathbb{P}_\mathcal{X}(f^{-1}(B))$ for any $B\in\mathcal{B}(\mathbb{R}^n)$. It follows that $\hat{\mathcal{Y}}_\epsilon^M:\Omega\rightarrow\mathcal{K}$ is a random compact set satisfying Definition 1 $^{4}$. Intuitively, different input samples $x_i(\omega)$ induce different output samples $y_i(\omega)$, resulting in different approximated compact reachable sets $\hat{\mathcal{Y}}_\epsilon^M(\omega)\in\mathcal{K}$, where $\omega\in\Omega$.""", [89, 275, 523, 353]),
 T(r"""Footnote 3: For a canonical construction, let $\Omega=\mathbb{R}^p\times\dots\times\mathbb{R}^p$ ($M$ times), $\mathcal{G}=\mathcal{B}(\mathbb{R}^p)\otimes\dots\otimes\mathcal{B}(\mathbb{R}^p)$, $\mathbb{P}=\mathbb{P}_\mathcal{X}\otimes\dots\otimes\mathbb{P}_\mathcal{X}$ the product measure, and $x=(x_1,\dots,x_M): \Omega\rightarrow\Omega: \omega\mapsto\omega$. Then, the $x_i$ are independent and have the law $\mathbb{P}_\mathcal{X}$.""", [95, 650, 523, 672]),
 T(r"""Footnote 4: Compactness of $\mathcal{X}$ and continuity of $f$ guarantee that both $\mathcal{Y}$ and $\hat{\mathcal{Y}}_\epsilon^M(\omega)$ are compact for any $\omega\in\Omega$. We refer to (Molchanov, 2017) and (Lew and Pavone, 2020) for a proof of measurability of $\hat{\mathcal{Y}}_\epsilon^M$.""", [95, 673, 523, 694]),
 H(r"## Appendix B. Proofs", [89, 373, 193, 386]),
 H(r"### B.1. Proof of Theorem 1", [89, 395, 205, 405]),
 T(r"""We first restate Assumption 1 and Theorem 1 from Section 4.""", [89, 414, 358, 425]),
 T(r"""**Assumption 1** $\mathbb{P}_\mathcal{X}(\{x\in\mathcal{X}: f(x)\in\mathring{B}(y,r)\})>0$ for all $y\in\partial\mathcal{Y}$ and all $r>0$.""", [89, 431, 445, 445]),
 T(r"""**Theorem 1** Let $\bar{\epsilon}\geq 0$ and $(\epsilon_M)_{M\in\mathbb{N}}$ be a sequence of padding radii such that $\epsilon_M\geq 0$ for all $M\in\mathbb{N}$ and $\epsilon_M\rightarrow \bar{\epsilon}$ as $M\rightarrow\infty$. For any $\epsilon\geq 0$, define the estimator $\hat{\mathcal{Y}}^M_{\epsilon}=\mathrm{H}\left(\{y_i\}_{i=1}^M\right)\oplus B(0,\epsilon)$. Then, under Assumption 1, $\mathbb{P}$-almost surely, as $M\rightarrow\infty$,""", [89, 452, 523, 491]),
 T(r"""$$
d_H(\hat{\mathcal{Y}}_{\epsilon_M}^M, \mathrm{H}(\mathcal{Y})\oplus B(0,\bar{\epsilon})) \longrightarrow 0.
$$""", [228, 495, 385, 521]),
 T(r"""**Proof** Denote $\hat{\mathcal{Y}}^M=\mathrm{H}(\{y_i\}_{i=1}^M)$, so that $\hat{\mathcal{Y}}^M_{\epsilon_M}=\mathrm{H}(\{y_i\}_{i=1}^M)\oplus B(0,\epsilon_M)$.""", [89, 526, 523, 540]),
 T(r"""To prove that almost surely, the sequence of random compact sets $\{\hat{\mathcal{Y}}^M_{\epsilon_M}(\omega), M\geq 1\}$ converges to $\mathrm{H}(\mathcal{Y})\oplus B(0,\bar{\epsilon})$ as $M\rightarrow\infty$, we verify the conditions (C1) and (C2) of Theorem 3.""", [89, 541, 523, 568]),
 T(r"""(C1): Let $K\in \mathcal{K}$ satisfy $(\mathrm{H}(\mathcal{Y})\oplus B(0,\bar{\epsilon}))\cap K = \emptyset$. Then, since $K$ and $\mathrm{H}(\mathcal{Y})\oplus B(0,\bar{\epsilon})$ are both closed, there exists some $\epsilon>0$ such that $(\mathrm{H}(\mathcal{Y})\oplus B(0,\bar{\epsilon}+\epsilon))\cap K = \emptyset$ $^{5}$.""", [89, 575, 523, 601]),
 T(r"""Next, since $\epsilon_M\rightarrow\bar{\epsilon}$ as $M\rightarrow\infty$, we have that $\bar{\epsilon}-\epsilon<\epsilon_M<\bar{\epsilon}+\epsilon$ for all $M\geq M_{\epsilon}$.""", [106, 602, 523, 613]),
 T(r"""Since $y_i(\omega)\in\mathcal{Y}$ almost surely for all $i$, $\hat{\mathcal{Y}}^M\subseteq\mathrm{H}(\mathcal{Y})$ almost surely for all $M\geq M_{\epsilon}$. Thus, for any $M\geq M_{\epsilon}$, $(\hat{\mathcal{Y}}^M\oplus B(0,\epsilon_M)) \subseteq (\mathrm{H}(\mathcal{Y})\oplus B(0,\epsilon_M)) \subset (\mathrm{H}(\mathcal{Y})\oplus B(0,\bar{\epsilon}+\epsilon))$.""", [89, 614, 523, 642]),
 T(r"""Footnote 5: More generally, given $A,B\in\mathcal{K}$, then $A\cap B=\emptyset$ implies that $A\cap(B\oplus B(0,\epsilon))=\emptyset$ for some $\epsilon>0$.""", [95, 695, 523, 706]),
 PNUM(16),
]
page(16, items, r"""Text and mathematics taken from the authors' TeX (main.tex lines 1461-1567), macros expanded, and compared with the 150-dpi render and two 230-dpi crops (Section A.2; Appendix B.1 with footnotes 3-5). First item is the conclusion of Theorem 3 (begun on page 15); it starts a new sentence, so no join. Printed peculiarity kept: in this conclusion the sets are printed WITHOUT hats, '{Y^M}_{M=1}^inf ... d_H(Y^M, Y) -> 0' (same in the TeX). Section A.2: the three parameters (M in N, eps > 0, probability measure P_X on (R^p, B(R^p)) with P_X(X) = 1) are one list item; footnote marks 3 and 4 are printed as superscripts after 'B(R^p)' and after 'Definition 1' and are written as '$^{3}$', '$^{4}$' separated by a space from the preceding formula (to avoid a '$$' sequence). Appendix B.1 restates Assumption 1 and Theorem 1 with bold labels (written with the printed punctuation, no period: '**Assumption 1**', '**Theorem 1**', '**Proof**') and upright text; the restated Theorem 1 says 'P-almost surely' (the main-text statement on page 5 says 'almost surely'); its display was an extractor formula image and is now LaTeX. Proof of Theorem 1, part (C1), first three steps checked symbol by symbol: (H(Y) (+) B(0,\bar eps)) cap K = empty; existence of eps > 0 with (H(Y) (+) B(0,\bar eps + eps)) cap K = empty (footnote mark 5); \bar eps - eps < eps_M < \bar eps + eps for all M >= M_eps; inclusion chain (\hat Y^M (+) B(0,eps_M)) subseteq (H(Y) (+) B(0,eps_M)) subset (H(Y) (+) B(0,\bar eps + eps)). The step label '(C1):' is an equation reference and is printed in normal weight (the TeX source wraps it in \textbf, but amsmath prints equation references in the normal font; PDF followed). Footnotes 3, 4 and 5 are all printed at the bottom of this page, i.e. below the first lines of the proof of Theorem 1 in Appendix B.1. Footnotes 3 and 4 belong to Section A.2 (their marks are in its last paragraph) and are placed at the end of Section A.2, before the 'Appendix B. Proofs' heading, so that they stay in the section that cites them; footnote 5 (mark in step (C1) of the proof) is kept at the bottom of the page, after the last proof sentence of the page, which is complete. 'Footnote n:' prefixes added. Headings fixed to '### A.2. ...', '## Appendix B. Proofs', '### B.1. Proof of Theorem 1'. Running header and page number 16 omitted.""")
